int early_return(int a) {
  return a;
  a += 1;
}

int loop_break(int a) {
  while (a > 0) {
    a -= 1;
    break;
    a -= 1;
  }
  return a;
}

int jump_target(int a) {
  goto skip;
  a += 1;
skip:
  return a;
}

int branch(int a) {
  if (a > 0) {
    return 1;
  } else {
    return 0;
  }
  a += 1;
}

int main(void) {
  return early_return(1) + loop_break(2) + jump_target(3) + branch(4);
}

